type Produk = { nama: string; harga: number };
type Respons<T> = { ok: true; data: T } | { ok: false; pesan: string };

function cariProduk(nama: string): Respons<Produk> {
  if (nama === "kopi") return { ok: true, data: { nama: "Kopi", harga: 18000 } };
  return { ok: false, pesan: `Produk ${nama} tidak ada` };
}
for (const n of ["kopi", "jus"]) {
  const r = cariProduk(n);
  console.log(r.ok ? r.data.harga : r.pesan);
}

