cards.solution:
type Halaman<T> = { isi: T[]; halaman: number; totalHalaman: number };
function pecah<T>(a: T[], ukuran: number, halaman: number): Halaman<T> {
  const mulai = (halaman - 1) * ukuran;
  return {
    isi: a.slice(mulai, mulai + ukuran),
    halaman,
    totalHalaman: Math.ceil(a.length / ukuran),
  };
}
const h = pecah([1, 2, 3, 4, 5, 6, 7], 3, 3);
console.log(h.isi);
console.log(h.totalHalaman);
